from runtime import build, read

def transform(payload, contract):
    """Return the business report described in SPEC.md. Leave caller inputs unchanged."""
    raise NotImplementedError

def load_payload(path):
    return read(path)

def build_component(root, contract):
    return build(root, contract, transform)

def fire_arrivals(request):
    "Accept the public request and return a rectangular list of lists with the grid shape. Each traversable cell contains its earliest integer ignition tick or None if never reached. Wall cells contain None. Use the stated seed times, orthogonal moves, and each entered cell's spread cost. Road closures restrict people only and leave fire propagation unaffected.\n\nLocal check: Use grid rows '...' and '..#', spread costs [[1, 2, 4], [3, 1, 1]], seeds at (0, 0) at tick 2 and (0, 2) at tick 1, and a closure covering (0, 1) at all test ticks. Assert the result is [[2, 3, 1], [5, 4, None]]."
    raise NotImplementedError

def plan_routes(request, hazard):
    'Accept the public request and a grid-shaped list of lists of ignition ticks or None. Return a dict with max_saved, total_arrival, evacuees, and shelters in the public result formats. Find a joint legal witness with the exact public lexicographic objective. Preserve shelter eligibility and cumulative capacity, release times, inclusive road closures, safety at the ignition boundary, cell occupancy through arrival, and opposing-edge conflicts.\n\nLocal check: Supply a three-cell row with None ignition times, no closures, and horizon 3. Two people release at tick 0 at opposite ends and each qualifies only for the shelter at the other end. Both shelters are open at ticks 0 through 3 and have capacity 1. Assert max_saved is 1, total_arrival is 2, and the witness uses exactly one valid shelter slot. Either person may be the one assigned.'
    raise NotImplementedError

import heapq
from collections import Counter


def fire_grid(q):
    grid=q['grid'];h=len(grid);w=len(grid[0]);dist={};queue=[]
    for s in q['fire_seeds']:
        p=(s['r'],s['c']);t=s['time']
        if grid[p[0]][p[1]]!='#' and t<dist.get(p,float('inf')):dist[p]=t;heapq.heappush(queue,(t,p))
    while queue:
        t,(r,c)=heapq.heappop(queue)
        if dist[r,c]!=t:continue
        for u,v in [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]:
            if 0<=u<h and 0<=v<w and grid[u][v]!='#':
                nt=t+q['spread_cost'][u][v]
                if nt<dist.get((u,v),float('inf')):dist[u,v]=nt;heapq.heappush(queue,(nt,(u,v)))
    return [[None if grid[r][c]=='#' else dist.get((r,c)) for c in range(w)] for r in range(h)]


def safe(q,fire,p,t):
    r,c=p
    return 0<=r<len(q['grid']) and 0<=c<len(q['grid'][0]) and q['grid'][r][c]!='#' and (fire[r][c] is None or t<fire[r][c]) and not any(e['r']==r and e['c']==c and e['start']<=t<=e['end'] for e in q['closures'])


def conflict(q,plans):
    names=list(plans)
    for t in range(q['max_ticks']+1):
        at={k:tuple(p['path'][t-p['release']]) for k,p in plans.items() if p['release']<=t<=p['arrival']}
        for i,k in enumerate(names):
            for j in names[i+1:]:
                if k in at and j in at and at[k]==at[j]:return ('vertex',(k,j),(t,at[k]))
                if t>0 and k in at and j in at and plans[k]['release']<t and plans[j]['release']<t:
                    oldk=tuple(plans[k]['path'][t-1-plans[k]['release']]);oldj=tuple(plans[j]['path'][t-1-plans[j]['release']])
                    if oldk==at[j] and oldj==at[k] and oldk!=at[k]:return ('edge',(k,j),(t-1,oldk,at[k]))
    for s in q['shelters']:
        users=[k for k,p in plans.items() if p['shelter']==s['id']]
        if len(users)>s['capacity']:return ('shelter',tuple(users[:s['capacity']+1]),s['id'])
    return None


def report(q,fire,plans):
    used=Counter(p['shelter'] for p in plans.values())
    return dict(max_saved=len(plans),total_arrival=sum(p['arrival'] for p in plans.values()),fire_arrival=fire,
        evacuees=[dict(id=e['id'],status='assigned',shelter=plans[e['id']]['shelter'],arrival=plans[e['id']]['arrival'],path=plans[e['id']]['path']) if e['id'] in plans else dict(id=e['id'],status='unassigned',shelter=None,arrival=None,path=[]) for e in q['evacuees']],
        shelters=[dict(id=s['id'],used=used[s['id']],capacity=s['capacity']) for s in q['shelters']])


