"""Fire spread model for the joint evacuation report."""

import heapq


def fire_arrivals(request):
    """Return the earliest ignition tick for every traversable cell.

    Fire spreads by orthogonal moves. Entering a neighbour costs that
    neighbour's ``spread_cost``. Seeds provide their own initial time. Walls
    and cells never reached by any seed are reported as ``None``. Road
    closures are deliberately ignored here: they restrict people only.
    """
    grid = request["grid"]
    spread = request["spread_cost"]
    height = len(grid)
    width = len(grid[0])

    infinity = float("inf")
    dist = [[infinity] * width for _ in range(height)]
    heap = []

    for seed in request["fire_seeds"]:
        r = seed["r"]
        c = seed["c"]
        t = seed["time"]
        if grid[r][c] != "#" and t < dist[r][c]:
            dist[r][c] = t
            heapq.heappush(heap, (t, r, c))

    while heap:
        t, r, c = heapq.heappop(heap)
        if t != dist[r][c]:
            continue
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= nr < height and 0 <= nc < width and grid[nr][nc] != "#":
                nt = t + spread[nr][nc]
                if nt < dist[nr][nc]:
                    dist[nr][nc] = nt
                    heapq.heappush(heap, (nt, nr, nc))

    return [
        [
            None if grid[r][c] == "#" or dist[r][c] == infinity else dist[r][c]
            for c in range(width)
        ]
        for r in range(height)
    ]

"""Joint evacuation planning.

The planner solves the exact lexicographic objective from SPEC.md:

  * first maximise the number of assigned people;
  * then minimise the sum of their absolute arrival times.

Agents (selected evacuees) move through a time-expanded safe grid. Conflicts
are resolved with Conflict-Based Search (CBS). Each low-level search is a
breadth-first search that returns a shortest (earliest-arrival) legal route
for one person under a set of negative constraints.
"""

import heapq
from collections import Counter, deque
from itertools import combinations


_MOVES = ((0, 0), (-1, 0), (1, 0), (0, -1), (0, 1))


class _Context:
    __slots__ = (
        "request", "grid", "height", "width", "max_ticks", "people",
        "shelters", "shelter_by_id", "safe", "neighbours",
    )

    def __init__(self, request, hazard):
        self.request = request
        self.grid = request["grid"]
        self.height = len(self.grid)
        self.width = len(self.grid[0])
        self.max_ticks = request["max_ticks"]
        self.people = request["evacuees"]
        self.shelters = request["shelters"]
        self.shelter_by_id = {s["id"]: s for s in self.shelters}
        self.safe = _build_safety(request, hazard)
        self.neighbours = _build_neighbours(self.grid)


def _build_safety(request, hazard):
    grid = request["grid"]
    height = len(grid)
    width = len(grid[0])
    closures = request["closures"]
    max_ticks = request["max_ticks"]
    safe = []
    for t in range(max_ticks + 1):
        layer = []
        for r in range(height):
            row = []
            for c in range(width):
                if grid[r][c] == "#":
                    row.append(False)
                    continue
                arrival = hazard[r][c]
                ok = arrival is None or t < arrival
                if ok:
                    for closure in closures:
                        if (closure["r"] == r and closure["c"] == c
                                and closure["start"] <= t <= closure["end"]):
                            ok = False
                            break
                row.append(ok)
            layer.append(row)
        safe.append(layer)
    return safe


def _build_neighbours(grid):
    height = len(grid)
    width = len(grid[0])
    neighbours = {}
    for r in range(height):
        for c in range(width):
            if grid[r][c] == "#":
                continue
            cells = [(r, c)]
            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                nr = r + dr
                nc = c + dc
                if 0 <= nr < height and 0 <= nc < width and grid[nr][nc] != "#":
                    cells.append((nr, nc))
            neighbours[(r, c)] = cells
    return neighbours


def _finish_shelter(ctx, person_index, r, c, t, bans):
    """Return a shelter id where this person may finish at (r, c, t)."""
    person = ctx.people[person_index]
    for shelter_id in person["eligible_shelters"]:
        if (person_index, shelter_id) in bans:
            continue
        shelter = ctx.shelter_by_id[shelter_id]
        if shelter["r"] == r and shelter["c"] == c and shelter["opens"] <= t < shelter["closes"]:
            return shelter_id
    return None


def _low_level(ctx, person_index, vertex_constraints, edge_constraints, bans):
    person = ctx.people[person_index]
    release = person["release"]
    start_r = person["r"]
    start_c = person["c"]

    if not ctx.safe[release][start_r][start_c]:
        return None
    if (person_index, start_r, start_c, release) in vertex_constraints:
        return None

    shelter_id = _finish_shelter(ctx, person_index, start_r, start_c, release, bans)
    if shelter_id is not None:
        return {
            "shelter": shelter_id,
            "arrival": release,
            "release": release,
            "path": [[start_r, start_c]],
        }

    start_state = (start_r, start_c, release)
    frontier = deque([start_state])
    visited = {start_state}
    previous = {}

    while frontier:
        r, c, t = frontier.popleft()
        if t == ctx.max_ticks:
            continue
        next_t = t + 1
        for nr, nc in ctx.neighbours[(r, c)]:
            if not ctx.safe[next_t][nr][nc]:
                continue
            if (person_index, nr, nc, next_t) in vertex_constraints:
                continue
            if (person_index, r, c, nr, nc, next_t) in edge_constraints:
                continue
            state = (nr, nc, next_t)
            if state in visited:
                continue
            visited.add(state)
            previous[state] = (r, c, t)
            shelter_id = _finish_shelter(ctx, person_index, nr, nc, next_t, bans)
            if shelter_id is not None:
                return {
                    "shelter": shelter_id,
                    "arrival": next_t,
                    "release": release,
                    "path": _reconstruct_path(previous, start_state, state),
                }
            frontier.append(state)

    return None


def _reconstruct_path(previous, start_state, final_state):
    cells = []
    state = final_state
    while state != start_state:
        cells.append([state[0], state[1]])
        state = previous[state]
    cells.append([start_state[0], start_state[1]])
    cells.reverse()
    return cells


class _Node:
    __slots__ = ("vertex", "edge", "bans", "paths", "cost")

    def __init__(self, vertex, edge, bans, paths, cost):
        self.vertex = vertex
        self.edge = edge
        self.bans = bans
        self.paths = paths
        self.cost = cost


def _constraint_key(vertex, edge, bans):
    return (tuple(sorted(vertex)), tuple(sorted(edge)), tuple(sorted(bans)))


def _find_conflict(ctx, paths, agents):
    max_ticks = ctx.max_ticks

    # Vertex conflicts first, in chronological order.
    for t in range(max_ticks + 1):
        active = [i for i in agents
                  if paths[i]["release"] <= t <= paths[i]["arrival"]]
        for a_pos in range(len(active)):
            a = active[a_pos]
            path_a = paths[a]
            offset_a = t - path_a["release"]
            cell_a = path_a["path"][offset_a]
            for b_pos in range(a_pos + 1, len(active)):
                b = active[b_pos]
                path_b = paths[b]
                cell_b = path_b["path"][t - path_b["release"]]
                if cell_a == cell_b:
                    return {
                        "type": "vertex",
                        "t": t,
                        "a": a,
                        "b": b,
                        "pos": cell_a,
                    }

    # Opposing-edge swaps.
    for t in range(1, max_ticks + 1):
        active = [i for i in agents
                  if paths[i]["release"] <= t - 1 <= paths[i]["arrival"]
                  and paths[i]["release"] <= t <= paths[i]["arrival"]]
        for a_pos in range(len(active)):
            a = active[a_pos]
            path_a = paths[a]
            a_prev = path_a["path"][t - 1 - path_a["release"]]
            a_cur = path_a["path"][t - path_a["release"]]
            if a_prev == a_cur:
                continue
            for b_pos in range(a_pos + 1, len(active)):
                b = active[b_pos]
                path_b = paths[b]
                b_prev = path_b["path"][t - 1 - path_b["release"]]
                b_cur = path_b["path"][t - path_b["release"]]
                if b_prev == b_cur:
                    continue
                if a_prev == b_cur and b_prev == a_cur:
                    return {
                        "type": "edge",
                        "t": t,
                        "a": a,
                        "b": b,
                        "a_prev": a_prev,
                        "a_cur": a_cur,
                        "b_prev": b_prev,
                        "b_cur": b_cur,
                    }

    # Shelter capacity conflicts.
    users_by_shelter = {}
    for i in agents:
        shelter_id = paths[i]["shelter"]
        users_by_shelter.setdefault(shelter_id, []).append(i)
    for shelter_id in sorted(users_by_shelter):
        users = users_by_shelter[shelter_id]
        if len(users) > ctx.shelter_by_id[shelter_id]["capacity"]:
            return {"type": "shelter", "sid": shelter_id, "users": users}

    return None


def _make_child(ctx, node, person_index, vertex_add=None, edge_add=None, ban_add=None):
    vertex = set(node.vertex)
    edge = set(node.edge)
    bans = set(node.bans)
    if vertex_add is not None:
        vertex.add(vertex_add)
    if edge_add is not None:
        edge.add(edge_add)
    if ban_add is not None:
        bans.add(ban_add)

    replacement = _low_level(ctx, person_index, vertex, edge, bans)
    if replacement is None:
        return None

    paths = dict(node.paths)
    old_arrival = paths[person_index]["arrival"]
    paths[person_index] = replacement
    cost = node.cost - old_arrival + replacement["arrival"]
    return _Node(vertex, edge, bans, paths, cost)


def _solve_subset(ctx, subset):
    agents = list(subset)
    if not agents:
        return {}

    vertex = set()
    edge = set()
    bans = set()
    paths = {}
    cost = 0
    for person_index in agents:
        result = _low_level(ctx, person_index, vertex, edge, bans)
        if result is None:
            return None
        paths[person_index] = result
        cost += result["arrival"]

    root = _Node(vertex, edge, bans, paths, cost)
    counter = 0
    heap = [(cost, counter, root)]
    counter += 1
    seen = {_constraint_key(vertex, edge, bans)}

    while heap:
        _, _, node = heapq.heappop(heap)
        conflict = _find_conflict(ctx, node.paths, agents)
        if conflict is None:
            return node.paths

        children = []
        if conflict["type"] == "vertex":
            t = conflict["t"]
            pos = conflict["pos"]
            a = conflict["a"]
            b = conflict["b"]
            children.append(_make_child(
                ctx, node, a, vertex_add=(a, pos[0], pos[1], t)))
            children.append(_make_child(
                ctx, node, b, vertex_add=(b, pos[0], pos[1], t)))
        elif conflict["type"] == "edge":
            t = conflict["t"]
            a = conflict["a"]
            b = conflict["b"]
            children.append(_make_child(
                ctx, node, a,
                edge_add=(a, conflict["a_prev"][0], conflict["a_prev"][1],
                          conflict["a_cur"][0], conflict["a_cur"][1], t)))
            children.append(_make_child(
                ctx, node, b,
                edge_add=(b, conflict["b_prev"][0], conflict["b_prev"][1],
                          conflict["b_cur"][0], conflict["b_cur"][1], t)))
        else:
            for user in conflict["users"]:
                children.append(_make_child(
                    ctx, node, user, ban_add=(user, conflict["sid"])))

        for child in children:
            if child is None:
                continue
            key = _constraint_key(child.vertex, child.edge, child.bans)
            if key in seen:
                continue
            seen.add(key)
            heapq.heappush(heap, (child.cost, counter, child))
            counter += 1

    return None


def _format_report(ctx, subset, paths):
    used = Counter(result["shelter"] for result in paths.values())
    evacuees = []
    for index, person in enumerate(ctx.people):
        if index in paths:
            result = paths[index]
            evacuees.append({
                "id": person["id"],
                "status": "assigned",
                "shelter": result["shelter"],
                "arrival": result["arrival"],
                "path": result["path"],
            })
        else:
            evacuees.append({
                "id": person["id"],
                "status": "unassigned",
                "shelter": None,
                "arrival": None,
                "path": [],
            })
    shelters = [
        {"id": shelter["id"], "used": used[shelter["id"]],
         "capacity": shelter["capacity"]}
        for shelter in ctx.shelters
    ]
    return {
        "max_saved": len(paths),
        "total_arrival": sum(result["arrival"] for result in paths.values()),
        "evacuees": evacuees,
        "shelters": shelters,
    }


def plan_routes(request, hazard):
    """Return the jointly optimal evacuation plan.

    ``hazard`` is the grid-shaped ignition matrix produced by
    ``hazard_model.fire_arrivals``.
    """
    ctx = _Context(request, hazard)
    total = len(ctx.people)

    for size in range(total, -1, -1):
        best = None
        for subset in combinations(range(total), size):
            paths = _solve_subset(ctx, subset)
            if paths is None:
                continue
            report = _format_report(ctx, subset, paths)
            if best is None or report["total_arrival"] < best["total_arrival"]:
                best = report
        if best is not None:
            return best

    # The empty subset is always feasible; this line is only a safety net.
    return _format_report(ctx, (), {})

