        if t == ctx.max_ticks:
            continue
        next_t = t + 1
        for nr, nc in ctx.neighbours[(r, c)]:
            if not ctx.safe[next_t][nr][nc]:
                continue
            if (person_index, nr, nc, next_t) in vertex_constraints:
                continue
            if (person_index, r, c, nr, nc, next_t) in edge_constraints:
                continue
            state = (nr, nc, next_t)
            if state in visited:
                continue
            visited.add(state)
            previous[state] = (r, c, t)
            shelter_id = _finish_shelter(ctx, person_index, nr, nc, next_t, bans)
            if shelter_id is not None:
                return {
                    "shelter": shelter_id,
                    "arrival": next_t,
                    "release": release,
                    "path": _reconstruct_path(previous, start_state, state),
                }
            frontier.append(state)

    return None


def _reconstruct_path(previous, start_state, final_state):
    cells = []
    state = final_state
    while state != start_state:
        cells.append([state[0], state[1]])
        state = previous[state]
    cells.append([start_state[0], start_state[1]])
    cells.reverse()
    return cells


class _Node:
    __slots__ = ("vertex", "edge", "bans", "paths", "cost")

    def __init__(self, vertex, edge, bans, paths, cost):
        self.vertex = vertex
        self.edge = edge
        self.bans = bans
        self.paths = paths
        self.cost = cost


def _constraint_key(vertex, edge, bans):
    return (tuple(sorted(vertex)), tuple(sorted(edge)), tuple(sorted(bans)))


def _find_conflict(ctx, paths, agents):
    max_ticks = ctx.max_ticks

    # Vertex conflicts first, in chronological order.
    for t in range(max_ticks + 1):
        active = [i for i in agents
                  if paths[i]["release"] <= t <= paths[i]["arrival"]]
        for a_pos in range(len(active)):
            a = active[a_pos]
            path_a = paths[a]
            offset_a = t - path_a["release"]
            cell_a = path_a["path"][offset_a]
            for b_pos in range(a_pos + 1, len(active)):
                b = active[b_pos]
                path_b = paths[b]
                cell_b = path_b["path"][t - path_b["release"]]
                if cell_a == cell_b:
                    return {
                        "type": "vertex",
                        "t": t,
                        "a": a,
                        "b": b,
                        "pos": cell_a,
                    }

    # Opposing-edge swaps.
    for t in range(1, max_ticks + 1):
        active = [i for i in agents
                  if paths[i]["release"] <= t - 1 <= paths[i]["arrival"]
                  and paths[i]["release"] <= t <= paths[i]["arrival"]]
        for a_pos in range(len(active)):
            a = active[a_pos]
            path_a = paths[a]
            a_prev = path_a["path"][t - 1 - path_a["release"]]
            a_cur = path_a["path"][t - path_a["release"]]
            if a_prev == a_cur:
                continue
            for b_pos in range(a_pos + 1, len(active)):
                b = active[b_pos]
                path_b = paths[b]
                b_prev = path_b["path"][t - 1 - path_b["release"]]
                b_cur = path_b["path"][t - path_b["release"]]
                if b_prev == b_cur:
                    continue
                if a_prev == b_cur and b_prev == a_cur:
                    return {
                        "type": "edge",
                        "t": t,
                        "a": a,
                        "b": b,
                        "a_prev": a_prev,
                        "a_cur": a_cur,
                        "b_prev": b_prev,
                        "b_cur": b_cur,
                    }

    # Shelter capacity conflicts.
    users_by_shelter = {}
    for i in agents:
        shelter_id = paths[i]["shelter"]
        users_by_shelter.setdefault(shelter_id, []).append(i)
    for shelter_id in sorted(users_by_shelter):
        users = users_by_shelter[shelter_id]
        if len(users) > ctx.shelter_by_id[shelter_id]["capacity"]:
            return {"type": "shelter", "sid": shelter_id, "users": users}

    return None


def _make_child(ctx, node, person_index, vertex_add=None, edge_add=None, ban_add=None):
    vertex = set(node.vertex)
    edge = set(node.edge)
    bans = set(node.bans)
    if vertex_add is not None:
        vertex.add(vertex_add)
    if edge_add is not None:
        edge.add(edge_add)
    if ban_add is not None:
        bans.add(ban_add)

    replacement = _low_level(ctx, person_index, vertex, edge, bans)
    if replacement is None:
        return None

    paths = dict(node.paths)
    old_arrival = paths[person_index]["arrival"]
    paths[person_index] = replacement
    cost = node.cost - old_arrival + replacement["arrival"]
    return _Node(vertex, edge, bans, paths, cost)


def _solve_subset(ctx, subset):
    agents = list(subset)
    if not agents:
        return {}

    vertex = set()
    edge = set()
    bans = set()
    paths = {}
    cost = 0
    for person_index in agents:
        result = _low_level(ctx, person_index, vertex, edge, bans)
        if result is None:
            return None
        paths[person_index] = result
        cost += result["arrival"]

    root = _Node(vertex, edge, bans, paths, cost)
    counter = 0
    heap = [(cost, counter, root)]
    counter += 1
    seen = {_constraint_key(vertex, edge, bans)}

    while heap:
        _, _, node = heapq.heappop(heap)
        conflict = _find_conflict(ctx, node.paths, agents)
        if conflict is None:
            return node.paths

        children = []
        if conflict["type"] == "vertex":
            t = conflict["t"]
            pos = conflict["pos"]
            a = conflict["a"]
            b = conflict["b"]
            children.append(_make_child(
                ctx, node, a, vertex_add=(a, pos[0], pos[1], t)))
            children.append(_make_child(
                ctx, node, b, vertex_add=(b, pos[0], pos[1], t)))
        elif conflict["type"] == "edge":
            t = conflict["t"]
            a = conflict["a"]
            b = conflict["b"]
            children.append(_make_child(
                ctx, node, a,
                edge_add=(a, conflict["a_prev"][0], conflict["a_prev"][1],
                          conflict["a_cur"][0], conflict["a_cur"][1], t)))
            children.append(_make_child(
                ctx, node, b,
                edge_add=(b, conflict["b_prev"][0], conflict["b_prev"][1],
                          conflict["b_cur"][0], conflict["b_cur"][1], t)))
        else:
            for user in conflict["users"]:
                children.append(_make_child(
                    ctx, node, user, ban_add=(user, conflict["sid"])))

        for child in children:
            if child is None:
                continue
            key = _constraint_key(child.vertex, child.edge, child.bans)
            if key in seen:
                continue
            seen.add(key)
            heapq.heappush(heap, (child.cost, counter, child))
            counter += 1

    return None


def _format_report(ctx, subset, paths):
    used = Counter(result["shelter"] for result in paths.values())
    evacuees = []
    for index, person in enumerate(ctx.people):
        if index in paths:
            result = paths[index]
            evacuees.append({
                "id": person["id"],
                "status": "assigned",
                "shelter": result["shelter"],
                "arrival": result["arrival"],
                "path": result["path"],
            })
        else:
            evacuees.append({
                "id": person["id"],
                "status": "unassigned",
                "shelter": None,
                "arrival": None,
                "path": [],
            })
    shelters = [
        {"id": shelter["id"], "used": used[shelter["id"]],
         "capacity": shelter["capacity"]}
        for shelter in ctx.shelters
    ]
    return {
        "max_saved": len(paths),
        "total_arrival": sum(result["arrival"] for result in paths.values()),
        "evacuees": evacuees,
        "shelters": shelters,
    }


def plan_routes(request, hazard):
    """Return the jointly optimal evacuation plan.

    ``hazard`` is the grid-shaped ignition matrix produced by
    ``hazard_model.fire_arrivals``.
    """
    ctx = _Context(request, hazard)
    total = len(ctx.people)

    for size in range(total, -1, -1):
        best = None
        for subset in combinations(range(total), size):
            paths = _solve_subset(ctx, subset)
            if paths is None:
                continue
            report = _format_report(ctx, subset, paths)
            if best is None or report["total_arrival"] < best["total_arrival"]:
                best = report
        if best is not None:
            return best

    # The empty subset is always feasible; this line is only a safety net.
    return _format_report(ctx, (), {})

