        "total_arrival": plan["total_arrival"],
        "fire_arrival": fire,
        "evacuees": plan["evacuees"],
        "shelters": plan["shelters"],
    }


def load_payload(path):
    return read(path)


def build_component(root, contract):
    return build(root, contract, transform)

